css:
:root {
  --re-bg: #f5f3f0;
  --re-card: #ffffff;
  --re-text: #3a3632;
  --re-text-secondary: #8a837a;
  --re-accent: #7B9CB5;
  --re-accent-hover: #6A8BA3;
  --re-accent-light: #D8E6EE;
  --re-border: #d6dce2;
  --re-success: #6a9e6f;
  --re-radius: 14px;
  --re-shadow: 0 2px 10px rgba(58,54,50,0.06);
}

.rhythm-echo {
  font-family: -apple-system, "PingFang SC", "Microsoft YaHei", sans-serif;
  background: var(--re-bg);
  color: var(--re-text);
  max-width: 420px;
  margin: 0 auto;
  padding: 24px 18px 28px;
  border-radius: var(--re-radius);
  box-sizing: border-box;
  text-align: center;
}

.re-header h2 {
  margin: 0 0 4px;
  font-size: 1.3rem;
  font-weight: 600;
  letter-spacing: 0.03em;
}

.re-subtitle {
  margin: 0 0 16px;
  font-size: 0.85rem;
  color: var(--re-text-secondary);
}

.re-mute-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  background: var(--re-card);
  border: 1px solid var(--re-border);
  border-radius: 8px;
  margin-bottom: 18px;
  font-size: 0.82rem;
}

.re-mute-label {
  color: var(--re-text-secondary);
}

.re-mute-value {
  font-weight: 600;
}

.re-mute-value.muted { color: #c0392b; }
.re-mute-value.not-muted { color: var(--re-success); }
.re-mute-value.unknown { color: var(--re-text-secondary); }

.re-mute-hint {
  color: #c0392b;
  font-size: 0.78rem;
}

.re-phase {
  font-size: 0.95rem;
  color: var(--re-text-secondary);
  margin-bottom: 14px;
  min-height: 1.4em;
}

.re-play-btn {
  width: 100%;
  padding: 12px 0;
  background: var(--re-accent-light);
  color: var(--re-accent-hover);
  border: none;
  border-radius: var(--re-radius);
  font-size: 0.95rem;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.2s, color 0.2s;
  margin-bottom: 16px;
}

.re-play-btn:hover:not(:disabled) {
  background: var(--re-accent);
  color: #fff;
}

.re-play-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.re-tap-btn {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  background: var(--re-accent);
  color: #fff;
  border: none;
  font-size: 1.2rem;
  font-weight: 600;
  cursor: pointer;
  box-shadow: var(--re-shadow), 0 4px 16px rgba(123,156,181,0.25);
  transition: transform 0.08s, background 0.15s;
  margin: 10px auto 18px;
  display: block;
}

.re-tap-btn:active {
  transform: scale(0.93);
  background: var(--re-accent-hover);
}

.re-tap-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  transform: none;
}

.re-feedback {
  margin: 10px 0 14px;
  padding: 12px;
  background: var(--re-card);
  border: 1px solid var(--re-border);
  border-radius: var(--re-radius);
  font-size: 0.9rem;
  min-height: 2em;
  display: flex;
  align-items: center;
  justify-content: center;
}

.re-replay-btn {
  width: 100%;
  padding: 11px 0;
  background: var(--re-card);
  color: var(--re-text);
  border: 1.5px solid var(--re-border);
  border-radius: var(--re-radius);
  font-size: 0.9rem;
  cursor: pointer;
  transition: all 0.2s;
}

.re-replay-btn:hover:not(:disabled) {
  border-color: var(--re-accent);
  background: var(--re-accent-light);
}

.re-status-bar {
  margin-top: 16px;
  padding: 7px 12px;
  background: var(--re-card);
  border: 1px solid var(--re-border);
  border-radius: var(--re-radius);
  font-size: 0.8rem;
  color: var(--re-text-secondary);
}
